class BytesIOCopy:
    """Mimic ``io.BytesIO`` but back it with a real (temporary) file so
    that it exposes a working ``fileno()``. This lets code under test
    pass ``sys.stdout``/``sys.stderr`` to APIs like
    :class:`subprocess.Popen` (e.g. ``subprocess.run(..., stdout=sys.stderr)``)
    without raising ``io.UnsupportedOperation`` while running under
    :class:`CliRunner`. Written data is also copied to another stream.

    .. versionadded:: 8.2
    """

    def __init__(self, copy_to: io.BytesIO) -> None:
        self._file = tempfile.TemporaryFile()
        self.copy_to = copy_to

    def __getattr__(self, name: str) -> t.Any:
        return getattr(self._file, name)

    def fileno(self) -> int:
        return self._file.fileno()

    def flush(self) -> None:
        self._file.flush()
        self.copy_to.flush()

    def write(self, b: ReadableBuffer) -> int:
        self.copy_to.write(b)
        return self._file.write(b)

    def getvalue(self) -> bytes:
        pos = self._file.tell()
        self._file.seek(0)
        data = self._file.read()
        self._file.seek(pos)
        return data

